type CommandOutcome =
  | {
      commandId: string;
      status: 'applied';
      clientCommandId: string;
      serverRevision: string;
    }
  | {
      commandId: string;
      status: 'conflict';
      currentRevision: string;
      reason: 'revision-mismatch' | 'draft-replaced' | 'already-sent';
    }
  | {
      commandId: string;
      status: 'rejected';
      reason: 'invalid' | 'forbidden' | 'attachment-unavailable';
    };

type MailboxEvent =
  | { type: 'message.upserted'; eventId: string; message: Message; clientCommandId?: string }
  | { type: 'message.removed'; eventId: string; messageId: string; revision: string }
  | { type: 'thread.updated'; eventId: string; thread: Thread }
  | { type: 'label.updated'; eventId: string; label: Label }
  | { type: 'draft.replaced'; eventId: string; draft: DraftDocument; clientCommandId?: string };

type MailboxDelta = {
  mailboxId: string;
  afterCursor: string;
  syncCursor: string;
  events: readonly MailboxEvent[];
  commandOutcomes: readonly CommandOutcome[];
  hasMore: boolean;
};

type ThreadDetail = {
  thread: Thread;
  messages: readonly Message[];
};

type MessageBodyResource = {
  messageId: string;
  sourceRevision: string;
  contentType: 'text/plain' | 'text/html';
  content: string;
  hasRemoteImages: boolean;
  attachmentIds: readonly string[];
};

type SaveDraftResult = {
  draft: DraftDocument;
  clientCommandId: string;
};

type SendAccepted = {
  status: 'accepted';
  commandId: string;
  clientCommandId: string;
  reconciliation: 'await-mailbox-delta';
};

type LabelCommandResult = {
  status: 'applied' | 'accepted';
  commandId: string;
  clientCommandId: string;
  threadRevision?: string;
};

interface MailboxGateway {
  getSnapshot(input: {
    mailboxId: string;
    labelId?: string;
    pageToken?: string;
    signal: AbortSignal;
  }): Promise<{ snapshot: MailboxSnapshot; nextPageToken?: string }>;
  getChanges(input: {
    mailboxId: string;
    after: string;
    signal: AbortSignal;
  }): Promise<MailboxDelta>;
  getThread(threadId: string, signal: AbortSignal): Promise<ThreadDetail>;
  getMessageBody(messageId: string, signal: AbortSignal): Promise<MessageBodyResource>;
  saveDraft(command: Extract<OutboxCommand, { kind: 'draft.save' }>): Promise<SaveDraftResult>;
  sendDraft(command: Extract<OutboxCommand, { kind: 'draft.send' }>): Promise<SendAccepted>;
  setThreadLabels(
    command: Extract<OutboxCommand, { kind: 'thread.labels.set' }>,
  ): Promise<LabelCommandResult>;
}

type MailboxDocument = {
  threadsById: Record<string, Thread>;
  messagesById: Record<string, Message>;
  labelsById: Record<string, Label>;
  draftsById: Record<string, DraftDocument>;
};

declare function upsertMessage(document: MailboxDocument, message: Message): void;
declare function removeMessage(document: MailboxDocument, messageId: string, revision: string): void;
declare function upsertThread(document: MailboxDocument, thread: Thread): void;
declare function upsertLabel(document: MailboxDocument, label: Label): void;
declare function replaceDraft(document: MailboxDocument, draft: DraftDocument): void;

function assertNever(value: never): never {
  throw new Error(`Unsupported mailbox event: ${String(value)}`);
}

function applyMailboxEvent(document: MailboxDocument, event: MailboxEvent): void {
  switch (event.type) {
    case 'message.upserted':
      upsertMessage(document, event.message);
      return;
    case 'message.removed':
      removeMessage(document, event.messageId, event.revision);
      return;
    case 'thread.updated':
      upsertThread(document, event.thread);
      return;
    case 'label.updated':
      upsertLabel(document, event.label);
      return;
    case 'draft.replaced':
      replaceDraft(document, event.draft);
      return;
    default:
      assertNever(event);
  }
}
